#include "stdlib/constants/float32/eulergamma.h"
#include "stdlib/constants/float32/pi.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/digammaf.h"
#include "stdlib/math/base/special/floorf.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/tanf.h"
#include <stdint.h>

// Minimum value of `x` for which the asymptotic expansion may be used directly:
static const float MIN_SAFE_ASYMPTOTIC = 10.0f;

// Threshold above which the asymptotic expansion's correction term is below single-precision epsilon:
static const float ASYMPTOTIC_THRESHOLD = 1.0e8f;

/* Begin auto-generated functions. The following functions are auto-generated. Do not edit directly. */

// BEGIN: polyval_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_p( const float x ) {
	return 0.08333333333333333f + (x * (-0.008333333333333333f + (x * (0.003968253968253968f + (x * -0.004166666666666667f)))));
}

// END: polyval_p

/**
* Evaluates the digamma function for a single-precision floating-point number.
*
* ## Method
*
* 1.  For \\(x \leq 0\\), we use the reflection formula
*
*     ```tex
*     \psi(1-x) = \psi(x) + \frac{\pi}{\tan(\pi x)}
*     ```
*
*     to make \\(x\\) positive.
*
* 2.  For positive integer \\(x \leq 10\\), we use the formula
*
*     ```tex
*     \psi(n) = -\gamma + \sum_{k=1}^{n-1} \frac{1}{k}
*     ```
*
*     where \\(\gamma\\) is the Euler-Mascheroni constant.
*
* 3.  For general positive \\(x\\), we apply the recurrence relation
*
*     ```tex
*     \psi(x+1) = \psi(x) + \frac{1}{x}
*     ```
*
*     until \\(x \geq 10\\) and then use the asymptotic expansion
*
*     ```tex
*     \psi(x) = \ln(x) - \frac{1}{2x} - \sum_{k=1}^{\infty} \frac{B_{2k}}{2k x^{2k}}
*     ```
*
*     where \\(B_{2k}\\) are Bernoulli numbers.
*
* ## Notes
*
* -   For `x` equal to a negative integer or zero, the function returns `NaN`.
*
* @param x    input value
* @return     function value
*
* @example
* float y = stdlib_base_digammaf( 1.0f );
* // returns ~-0.577f
*/
float stdlib_base_digammaf( const float x ) {
	float rem;
	float tmp;
	float xx;
	float s;
	float w;
	float y;
	float z;
	int32_t i;
	int32_t n;
	int32_t negative;

	xx = x;
	negative = 0;

	if ( stdlib_base_is_nanf( x ) ) {
		return x;
	}

	// Handle negative arguments using reflection formula...
	if ( xx <= 0.0f ) {
		negative = 1;

		// Argument reduction for tan:
		rem = xx - stdlib_base_floorf( xx );

		// Check for singularity (negative integer or zero)...
		if ( rem == 0.0f ) {
			return 0.0f / 0.0f; // NaN
		}

		if ( rem == 0.5f ) {
			tmp = 0.0f;
		} else {
			if ( rem > 0.5f ) {
				rem = xx - ( stdlib_base_floorf( xx ) + 1.0f );
			}
			tmp = STDLIB_CONSTANT_FLOAT32_PI / stdlib_base_tanf( STDLIB_CONSTANT_FLOAT32_PI * rem );
		}

		// Reflect:
		xx = 1.0f - xx;
	} else {
		tmp = 0.0f;
	}

	// Use direct formula for small positive integers...
	if ( ( xx <= MIN_SAFE_ASYMPTOTIC ) && ( xx == stdlib_base_floorf( xx ) ) ) {
		y = 0.0f;
		n = (int32_t)xx;
		for ( i = 1; i < n; i++ ) {
			w = (float)i;
			y += 1.0f / w;
		}
		y -= STDLIB_CONSTANT_FLOAT32_EULERGAMMA;
		if ( negative ) {
			y -= tmp;
		}
		return y;
	}

	// Use recurrence to make x large enough for asymptotic expansion...
	s = xx;
	w = 0.0f;
	while ( s < MIN_SAFE_ASYMPTOTIC ) {
		w += 1.0f / s;
		s += 1.0f;
	}

	// Asymptotic expansion...
	if ( s < ASYMPTOTIC_THRESHOLD ) {
		z = 1.0f / ( s * s );
		y = z * polyval_p( z );
	} else {
		y = 0.0f;
	}

	y = stdlib_base_lnf( s ) - ( 0.5f / s ) - y - w;
	if ( negative ) {
		y -= tmp;
	}
	return y;
}
